import {uploadFile} from './upload.js';
export function createTemplateCatalogUI({api,getState,esc,toast,openDialog,closeDialog,refresh}){
 let active=false,admin=false,data={templates:[],sectors:[]},filter='',search='',ticket=0;
 const endpoint=()=>'/api/portal/template-catalog'+(admin?'?admin=1':'');
 function page(isAdmin=false){admin=isAdmin;return `<section class="page-heading"><div><p class="overline">BIBLIOTECA HELPU</p><h1>Templates por setor.</h1><p>${admin?'Prepare imagens e vídeos, organize por setor e publique quando estiverem prontos.':'Escolha uma inspiração e adapte com o Astra à identidade da sua empresa.'}</p></div></section><div id="template-catalog">Carregando…</div>`;}
 function fragment(){return '<details class="creative-library-group"><summary><strong>Templates da Helpu</strong><span>Explorar por setor</span></summary><p>Modelos publicados pela equipe. Adicionar à sua biblioteca não gera nem cobra conteúdo.</p><div id="template-catalog">Carregando…</div></details>';}
 async function load(){const t=++ticket;try{const result=await api(endpoint());if(!active||t!==ticket)return;data=result;render();}catch(e){if(active&&t===ticket)document.querySelector('#template-catalog').textContent=e.message;}}
 function render(){const el=document.querySelector('#template-catalog');if(!el)return;const sectors=[...new Set([...data.sectors,...data.templates.flatMap(t=>t.sectors)])];const items=data.templates.filter(t=>(!filter||t.sectors.includes(filter))&&(!search||(t.name+' '+t.description).toLocaleLowerCase('pt-BR').includes(search.toLocaleLowerCase('pt-BR'))));el.innerHTML=`${admin?'<button class="p-button primary" data-template="new">Adicionar template</button>':''}<div class="template-filters"><label>Setor<select id="template-sector"><option value="">Todos os setores</option>${sectors.map(s=>`<option ${s===filter?'selected':''} value="${esc(s)}">${esc(s)}</option>`).join('')}</select></label><label>Buscar<input id="template-search" type="search" value="${esc(search)}" placeholder="Nome ou descrição"></label></div><div class="creative-library-grid">${items.map(t=>`<article class="creative-file">${t.format==='video'?`<video controls preload="metadata" src="${esc(t.assetUrl)}"></video>`:`<img loading="lazy" src="${esc(t.assetUrl)}" alt="${esc(t.name)}">`}<h3>${esc(t.name)}</h3><p>${esc(t.sectors.join(' · '))}</p><p>${esc(t.description)}</p>${admin?`<p>${({draft:'Rascunho',published:'Publicado para clientes',archived:'Arquivado'})[t.state]}</p>`:''}<button class="p-button secondary" data-template="${admin?'edit':'adopt'}" data-id="${esc(t.id)}">${admin?'Editar / publicar':'Usar como inspiração'}</button></article>`).join('')||'<p>Nenhum template disponível para este filtro.</p>'}</div>`;}
 function editor(item){const org=getState().company.id;openDialog(item?'Editar template':'Adicionar template',`<form id="template-form"><label class="p-field">Nome<input name="name" maxlength="100" required value="${esc(item?.name||'')}"></label><label class="p-field">Setores (separados por vírgula, até cinco)<input name="sectors" list="template-sectors" required value="${esc(item?.sectors.join(', ')||'')}"><datalist id="template-sectors">${data.sectors.map(s=>`<option value="${esc(s)}">`).join('')}</datalist></label><label class="p-field">Descrição e orientação visual<textarea name="description" maxlength="3000">${esc(item?.description||'')}</textarea></label><label class="p-field">Imagem ou vídeo<input name="file" type="file" ${item?'':'required'} accept="image/png,image/jpeg,image/webp,video/mp4"></label><label class="p-field">Visibilidade<select name="state">${[['draft','Rascunho — só equipe'],['published','Publicado — disponível aos clientes'],['archived','Arquivado — oculto para clientes']].map(([v,n])=>`<option value="${v}" ${item?.state===v?'selected':''}>${n}</option>`).join('')}</select></label><p>Publique apenas materiais preparados para a biblioteca compartilhada. Arquivos particulares de clientes ficam nas bibliotecas das respectivas empresas.</p><button class="p-button primary">Salvar template</button><p role="alert" id="template-error"></p></form>`,true);const form=document.querySelector('#template-form');form.addEventListener('submit',async e=>{e.preventDefault();const b=form.querySelector('button');b.disabled=true;try{const d=new FormData(form),file=form.elements.file.files[0];let assetId=item?.assetId;if(file){if(file.size>25*1024*1024)throw Error('Use arquivo de até 25 MB.');assetId=(await uploadFile('/api/portal/'+(item?.orgId||org)+'/files',file)).id;}await api(endpoint(),'POST',{action:'save',id:item?.id,version:item?.version,orgId:org,assetId,name:d.get('name'),sectors:d.get('sectors').split(','),description:d.get('description'),state:d.get('state')});closeDialog();await load();toast('Template salvo.');}catch(err){document.querySelector('#template-error').textContent=err.message;}finally{b.disabled=false;}});}
 document.addEventListener('click',async e=>{const b=e.target.closest('[data-template]');if(!b||!active)return;try{if(b.dataset.template==='new')return editor();const item=data.templates.find(t=>t.id===b.dataset.id);if(!item)return;if(b.dataset.template==='edit')return editor(item);b.disabled=true;const org=getState().company.id;await api('/api/portal/'+org+'/template-catalog','POST',{id:item.id});if(getState().company.id===org){await refresh?.();toast('Inspiração adicionada à biblioteca desta empresa.');}}catch(err){toast(err.message,true);}finally{b.disabled=false;}});
 document.addEventListener('change',e=>{if(!active)return;if(e.target.id==='template-sector'){filter=e.target.value;render();}if(e.target.id==='template-search'){search=e.target.value;render();}});
 return {page,fragment,mount(view){active=view==='templates'||view==='studio';if(view==='studio')admin=false;++ticket;if(active)load();}};
}
